<?php view('community-assets');$now=date('Y-m-d H:i:s');$open=(!$call['start_at']||$call['start_at']<=$now)&&(!$call['end_at']||$call['end_at']>=$now); ?>
<div class="heading"><a class="outline" href="<?= e(url('calls')) ?>">همه فراخوان‌ها</a></div><div class="community-call-detail"><aside class="panel"><?php if($call['poster_asset_id']): ?><img class="call-poster" src="<?= e(url('asset',['id'=>$call['poster_asset_id']])) ?>" alt="پوستر فراخوان"><?php endif ?><p class="badge"><?= $open?'پذیرش اثر باز است':'در زمان فعلی پذیرش ندارد' ?></p><p>حداکثر <?= fa($call['max_entries']) ?> اثر برای هر حساب</p><p>هر فایل تا <?= fa(round($call['criteria']['max_file_bytes']/1048576)) ?> مگابایت</p><p class="hint">تاریخ‌ها میلادی و ساعت تهران هستند.</p><p>آغاز: <?= e($call['start_at']?:'زمان انتشار') ?></p><p>پایان: <?= e($call['end_at']?:'تعیین نشده') ?></p><?php if($open): ?><a class="primary" href="<?= e(url('submit-art',['call_id'=>$call['id']])) ?>">ارسال اثر به این فراخوان</a><?php endif ?></aside><section class="panel"><h1><?= e($call['title']) ?></h1><div class="prose"><?= nl2br(e($call['description'])) ?></div><?php if($call['terms']): ?><h2>رشته‌ها و نوع‌های مجاز</h2><div class="pillbar"><?php foreach($call['terms'] as $term): ?><span class="pill"><?= e($term['title']) ?></span><?php endforeach ?></div><?php endif ?><?php if($call['martyrs']): ?><h2>شهدا و افراد منتخب</h2><div class="pillbar"><?php foreach($call['martyrs'] as $person): ?><a class="pill" href="<?= e(url('profile',['id'=>$person['id']])) ?>"><?= e($person['first_name'].' '.$person['last_name']) ?></a><?php endforeach ?></div><?php endif ?><h2>شرایط ارسال و انتشار</h2><p class="prose"><?= nl2br(e($call['terms_text'])) ?></p><p class="notice">ارسال، به معنی پذیرش یا انتشار فوری نیست. نتیجه و درخواست اصلاح از حساب کاربری پیگیری می‌شود.</p></section></div>
